extension Duration {
  /// The shortest preset that lasts at least `seconds` (never .infinite or .custom).
  public static func atLeast(seconds: Int) -> Duration? {
    allCases.filter { $0 != .infinite && $0 != .custom }
      .sorted { $0.rawValue < $1.rawValue }
      .first { $0.rawValue >= seconds }.rawValue
  }
}

